export const fuelNames={electric:'Electric',mild_hybrid:'Mild hybrid',plug_in_hybrid:'Plug-in hybrid',petrol:'Petrol',diesel:'Diesel',unknown:'See details'};
export const initialEhubFilters={query:'',brand:'all',condition:'all',fuel:'all',budget:0,sort:'featured'};
const normal=value=>String(value).toLocaleLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'');
export function filterEhub(models,input={}){const s={...initialEhubFilters,...input},q=normal(s.query.trim());return models.filter(m=>(!q||normal([m.brand,m.model,m.reference,m.color].join(' ')).includes(q))&&(s.brand==='all'||s.brand===m.brand)&&(s.condition==='all'||s.condition===m.condition)&&(s.fuel==='all'||s.fuel===m.powertrain)&&(!s.budget||m.price<=Number(s.budget))).sort((a,b)=>s.sort==='price-low'?a.price-b.price||a.order-b.order:s.sort==='price-high'?b.price-a.price||a.order-b.order:s.sort==='saving'?b.saving-a.saving||a.order-b.order:s.sort==='name'?`${a.brand} ${a.model}`.localeCompare(`${b.brand} ${b.model}`):a.order-b.order);}
export function nextComparison(current,id){if(current.includes(id))return {ids:current.filter(x=>x!==id),error:''};if(current.length>=3)return {ids:current,error:'You can compare up to 3 cars. Remove one to add another.'};return {ids:[...current,id],error:''};}
export const escapeEhub=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
